files.patch:
@@ -1,37 +0,0 @@
-From f5d4fd186c68913240c4f6e9cda98443e1518b34 Mon Sep 17 00:00:00 2001
-From: BapToutatis <monsterbat02@gmail.com>
-Date: Tue, 6 Oct 2026 06:22:28 +0200
-Subject: [PATCH] avformat/rtsp: limit the number of redirects
-
-Fixes: 2OgPp3duxpWM
-Found-by: BapToutatis
-Endless redirect loop Replicated through UnModified FFmpeg with rogue RTSP servers
-Signed-off-by: Michael Niedermayer <michael@niedermayer.cc>
----
- libavformat/rtsp.c | 6 ++++++
- 1 file changed, 6 insertions(+)
-
-diff --git a/libavformat/rtsp.c b/libavformat/rtsp.c
-index cdf7b7c389bb3..eef1e10eb218f 100644
---- a/libavformat/rtsp.c
-+++ b/libavformat/rtsp.c
-@@ -1935,6 +1935,7 @@ int ff_rtsp_connect(AVFormatContext *s)
-     int port, err, tcp_fd;
-     RTSPMessageHeader reply1, *reply = &reply1;
-     int lower_transport_mask = 0;
-+    int redirects = 0;
-     int default_port = RTSP_DEFAULT_PORT;
-     int https_tunnel = 0;
-     char real_challenge[64] = "";
-@@ -2243,6 +2244,11 @@ int ff_rtsp_connect(AVFormatContext *s)
-     if (reply->status_code >=300 && reply->status_code < 400 && s->iformat) {
-         int ret;
- 
-+        if (redirects++ >= 8 /* MAX_RTSP_REDIRECTS */) {
-+            av_log(s, AV_LOG_ERROR, "Too many RTSP redirects\n");
-+            err = AVERROR(EIO);
-+            goto fail2;
-+        }
-         if (!rtsp_url_same_origin(s->url, reply->location)) {
-             memset(rt->auth, 0, sizeof(rt->auth));
-             memset(&rt->auth_state, 0, sizeof(rt->auth_state));
